    "formatName": "mov,mp4 (AVFoundation adapter)"
  },
  "transcript": {
    "segments": [
      {
        "start": 0,
        "end": 1.66,
        "text": "嗨 大家好 三三"
      },
      {
        "start": 1.66,
        "end": 2.44,
        "text": "前两个月呢"
      },
      {
        "start": 2.44,
        "end": 3.68,
        "text": "我在抖音精选推荐了"
      },
      {
        "start": 3.68,
        "end": 4.84,
        "text": "包位保障AI博主"
      },
      {
        "start": 4.84,
        "end": 6,
        "text": "都举关注了吗"
      },
      {
        "start": 6,
        "end": 7.32,
        "text": "好多朋友访问说啊"
      },
      {
        "start": 7.32,
        "end": 8.72,
        "text": "跟这里面的大老选"
      },
      {
        "start": 8.72,
        "end": 10.92,
        "text": "半天时间就把本地模型给部署好了"
      },
      {
        "start": 10.92,
        "end": 12.56,
        "text": "还今天虽然我在跟你一起"
      },
      {
        "start": 12.56,
        "end": 13.16,
        "text": "今天呢"
      },
      {
        "start": 13.16,
        "end": 14.4,
        "text": "有金靠系选的五位"
      },
      {
        "start": 14.4,
        "end": 16.2,
        "text": "敷散级的优质AI博主"
      },
      {
        "start": 16.2,
        "end": 17.44,
        "text": "从零基础入门"
      },
      {
        "start": 17.44,
        "end": 19.84,
        "text": "直上提下到创意变现全覆盖"
      },
      {
        "start": 19.84,
        "end": 21.16,
        "text": "说到你就赚到了"
      },
      {
        "start": 21.16,
        "end": 23.84,
        "text": "先说最适合新手入门的信统教学派"
      },
      {
        "start": 23.84,
        "end": 25.08,
        "text": "专门这教程看来"
      },
      {
        "start": 25.08,
        "end": 26.6,
        "text": "但不会用的AI配变"
      },
      {
        "start": 26.6,
        "end": 28.04,
        "text": "主打一步步带你吃草"
      },
      {
        "start": 30.4,
        "end": 31.76,
        "text": "大师的AI小兆"
      },
      {
        "start": 31.76,
        "end": 33.36,
        "text": "普通人选AI最大的痛苦啊"
      },
      {
        "start": 33.36,
        "end": 34.52,
        "text": "不是不能改变"
      },
      {
        "start": 34.52,
        "end": 36.24,
        "text": "而是看完教程一关视频"
      },
      {
        "start": 36.24,
        "end": 37.84,
        "text": "打开软件还是一脸梦"
      },
      {
        "start": 37.84,
        "end": 38.6,
        "text": "它内容呢"
      },
      {
        "start": 38.6,
        "end": 40.44,
        "text": "就专攻日常高频场景"
      },
      {
        "start": 40.44,
        "end": 42.48,
        "text": "理由用AI做大偏感TVT"
      },
      {
        "start": 42.48,
        "end": 44.28,
        "text": "优化深层视频提示词"
      },
      {
        "start": 44.28,
        "end": 45.44,
        "text": "用AI修图的"
      },
      {
        "start": 45.44,
        "end": 47.2,
        "text": "它就像给你一堆一开小兆"
      },
      {
        "start": 47.2,
        "end": 48.56,
        "text": "不光想操作步骤"
      },
      {
        "start": 48.56,
        "end": 50.64,
        "text": "还会讲清楚思路和指令逻辑"
      },
      {
        "start": 50.64,
        "end": 51.92,
        "text": "比如用AI做TVT"
      },
      {
        "start": 51.92,
        "end": 53.28,
        "text": "它不是人给你跟魔法"
      },
      {
        "start": 53.28,
        "end": 54.32,
        "text": "让你照的天"
      },
      {
        "start": 54.32,
        "end": 57.28,
        "text": "而是将你把如何描述清楚想要什么风格"
      },
      {
        "start": 57.28,
        "end": 59.28,
        "text": "让AI能够帮你大建出框架"
      },
      {
        "start": 59.28,
        "end": 60.64,
        "text": "配色和排板"
      },
      {
        "start": 60.64,
        "end": 61.64,
        "text": "看完它的视频"
      },
      {
        "start": 61.64,
        "end": 63.04,
        "text": "你不会觉得自己爱学AI"
      },
      {
        "start": 63.04,
        "end": 64.96,
        "text": "更像是旁边做了个董行的朋友"
      },
      {
        "start": 64.96,
        "end": 66.48,
        "text": "说把手将你把TBT"
      },
      {
        "start": 66.48,
        "end": 68.32,
        "text": "修补视频提示词"
      },
      {
        "start": 68.32,
        "end": 69.92,
        "text": "这些日常高频的火给干了"
      },
      {
        "start": 69.92,
        "end": 71.88,
        "text": "如果你到现在还只会跟AI说"
      },
      {
        "start": 71.88,
        "end": 72.68,
        "text": "你好"
      },
      {
        "start": 72.68,
        "end": 73.92,
        "text": "然后不再会干嘛"
      },
      {
        "start": 73.92,
        "end": 75.08,
        "text": "天看它就对了"
      },
      {
        "start": 75.08,
        "end": 76.96000000000001,
        "text": "第二位能理同学"
      },
      {
        "start": 76.96000000000001,
        "end": 78.12,
        "text": "想生跟AI会化"
      },
      {
        "start": 78.12,
        "end": 79.24,
        "text": "AI视频创作了"
      },
      {
        "start": 79.24,
        "end": 80.64,
        "text": "直接損死它"
      },
      {
        "start": 80.64,
        "end": 83.24,
        "text": "很多人想玩AI会化或AI视频的"
      },
      {
        "start": 83.24,
        "end": 84.64,
        "text": "第一步就被卡死"
      },
      {
        "start": 84.64,
        "end": 85.68,
        "text": "不然间装不上"
      },
      {
        "start": 85.68,
        "end": 86.64,
        "text": "报处看不懂"
      },
      {
        "start": 86.64,
        "end": 87.68,
        "text": "参数不会挑"
      },
      {
        "start": 87.68,
        "end": 88.6,
        "text": "能理同学呢"
      },
      {
        "start": 88.6,
        "end": 89.56,
        "text": "从下载安装"
      },
      {
        "start": 89.56,
        "end": 90.48,
        "text": "参数调试"
      },
      {
        "start": 90.48,
        "end": 92.03999999999999,
        "text": "到最终成片的整条路"
      },
      {
        "start": 92.03999999999999,
        "end": 93.44,
        "text": "全都自己先走一遍"
      },
      {
        "start": 93.44,
        "end": 94.4,
        "text": "再把踩过的坑"
      },
      {
        "start": 94.4,
        "end": 95.4,
        "text": "不要出来给你看"
      },
      {
        "start": 95.4,
        "end": 96.47999999999999,
        "text": "还会为你提前规避"
      },
      {
        "start": 96.47999999999999,
        "end": 98.52000000000001,
        "text": "操作中可能遇到问题和卡点"
      },
      {
        "start": 98.52000000000001,
        "end": 99.88,
        "text": "别人的价程只告诉你"
      },
      {
        "start": 99.88,
        "end": 101.03999999999999,
        "text": "挑这个参数"
      },
      {
        "start": 101.03999999999999,
        "end": 101.75999999999999,
        "text": "它会告诉你"
      },
      {
        "start": 101.75999999999999,
        "end": 103.16,
        "text": "这个参数动了之后"
      },
      {
        "start": 103.16,
        "end": 104.6,
        "text": "画面具体哪些会变"
      },
      {
        "start": 104.6,
        "end": 106.47999999999999,
        "text": "以及出问题是怎么排查"
      },
      {
        "start": 106.47999999999999,
        "end": 108.56,
        "text": "还要针对从夜人与人进階交称"
      },
      {
        "start": 108.56,
        "end": 109.6,
        "text": "不管有没有基础"
      },
      {
        "start": 109.6,
        "end": 112.08,
        "text": "跟着它动能从零做出完整的AI作品"
      },
      {
        "start": 112.08,
        "end": 113.44,
        "text": "想靠AI做视觉内容的"
      },
      {
        "start": 113.44,
        "end": 114.52000000000001,
        "text": "必须帮助一波"
      },
      {
        "start": 114.52000000000001,
        "end": 116.52000000000001,
        "text": "第二类是硬核实战派"
      },
      {
        "start": 116.52000000000001,
        "end": 117.72,
        "text": "不讲空犯概念"
      },
      {
        "start": 117.72,
        "end": 119.28,
        "text": "虽用内容的笨的落地"
      },
      {
        "start": 119.28,
        "end": 120.56,
        "text": "以效比搞减确"
      },
      {
        "start": 120.56,
        "end": 122.16,
        "text": "很多人学义对AI工具"
      },
      {
        "start": 122.16,
        "end": 123.48,
        "text": "最后发现只是在玩"
      },
      {
        "start": 123.48,
        "end": 125.16,
        "text": "没有变成真正的生产力"
      },
      {
        "start": 125.16,
        "end": 126.64,
        "text": "数字有目人不一样"
      },
      {
        "start": 126.64,
        "end": 128.32,
        "text": "它是浅微软工程师"
      },
      {
        "start": 128.32,
        "end": 130.52,
        "text": "虽玩法却是它自己先跑通"
      },
      {
        "start": 130.52,
        "end": 132.28,
        "text": "验证能落地的才发出来"
      },
      {
        "start": 132.28,
        "end": 135,
        "text": "它能加点如何大件一整套AI工作流"
      },
      {
        "start": 135,
        "end": 137.24,
        "text": "比如让几个AI智能体护相配合"
      },
      {
        "start": 137.24,
        "end": 138.8,
        "text": "自动完成收集资料"
      },
      {
        "start": 138.8,
        "end": 140.8,
        "text": "解除稿 改革式的流程"
      },
      {
        "start": 140.8,
        "end": 142.07999999999998,
        "text": "实现自动化办公"
      },
      {
        "start": 142.07999999999998,
        "end": 143.56,
        "text": "把你从中解放出来"
      },
      {
        "start": 143.56,
        "end": 145.6,
        "text": "或者直接把一个AI变现项目的"
      },
      {
        "start": 145.6,
        "end": 147.12,
        "text": "完整路警参与给你看"
      },
      {
        "start": 147.12,
        "end": 148.2,
        "text": "从需求在哪"
      },
      {
        "start": 148.2,
        "end": 149.76,
        "text": "用什么工具 怎么交互"
      },
      {
        "start": 149.76,
        "end": 150.88,
        "text": "全是具体的资产"
      },
      {
        "start": 150.88,
        "end": 152.6,
        "text": "高階提效技巧干货"
      },
      {
        "start": 152.6,
        "end": 154.4,
        "text": "它内容主打一个学了军能用"
      },
      {
        "start": 154.4,
        "end": 155.6,
        "text": "用了罪友结果"
      },
      {
        "start": 155.6,
        "end": 156.88,
        "text": "先把AI变成生产力"
      },
      {
        "start": 156.88,
        "end": 158.24,
        "text": "靠AI搞副业转型的"
      },
      {
        "start": 158.24,
        "end": 159.07999999999998,
        "text": "避看"
      },
      {
        "start": 159.07999999999998,
        "end": 160.12,
        "text": "那有人要说了"
      },
      {
        "start": 160.12,
        "end": 161.04,
        "text": "叫什么台褲子了"
      },
      {
        "start": 161.04,
        "end": 162.04,
        "text": "我不想学"
      },
      {
        "start": 162.04,
        "end": 163.8,
        "text": "我就想用AI找点创意灵感"
      },
      {
        "start": 163.8,
        "end": 165.56,
        "text": "那你一定要看下面这两位"
      },
      {
        "start": 167.36,
        "end": 168.88,
        "text": "如果你看教育成就犯困"
      },
      {
        "start": 168.88,
        "end": 170.4,
        "text": "只想知道现在这些AI道理"
      },
      {
        "start": 170.4,
        "end": 172.04,
        "text": "谁更聪明 谁会骗人"
      },
      {
        "start": 172.04,
        "end": 173,
        "text": "谁更靠谱"
      },
      {
        "start": 173,
        "end": 174.76,
        "text": "那工与商行会是为你了做"
      },
      {
        "start": 174.76,
        "end": 177.2,
        "text": "它的内容主打AI创意制斗军情"
      },
      {
        "start": 177.2,
        "end": 179.88,
        "text": "把不同的AI戴萌形放进游戏规则里"
      },
      {
        "start": 179.88,
        "end": 181.48,
        "text": "做出了像AI气大势重"
      },
      {
        "start": 181.48,
        "end": 182.12,
        "text": "综艺感"
      },
      {
        "start": 182.12,
        "end": 183.88,
        "text": "博弈感拉满的创意内容"
      },
      {
        "start": 183.88,
        "end": 186.04,
        "text": "你不是再看枯燥的参数的比表"
      },
      {
        "start": 186.04,
        "end": 187.48,
        "text": "而是再用看电影的方式"
      },
      {
        "start": 187.48,
        "end": 189.64,
        "text": "但你看新各家AI的真实能力"
      },
      {
        "start": 189.64,
        "end": 190.68,
        "text": "看乐泽时候"
      },
      {
        "start": 190.68,
        "end": 192.64,
        "text": "真实就这样繳滑金融年老子"
      },
      {
        "start": 194.52,
        "end": 196.32,
        "text": "这应该是很多视频创作者"
      },
      {
        "start": 196.32,
        "end": 198.4,
        "text": "和视觉一处爱好者的保障博主"
      },
      {
        "start": 198.4,
        "end": 200.2,
        "text": "它把AI技术和传统隐试"
      },
      {
        "start": 200.2,
        "end": 201.88,
        "text": "是挺集合的非常完美"
      },
      {
        "start": 201.88,
        "end": 204.2,
        "text": "只要怎么用AI工具去服务电影感"
      },
      {
        "start": 204.2,
        "end": 206.44,
        "text": "而不是被AI的默认效果带着跑"
      },
      {
        "start": 206.44,
        "end": 209.32,
        "text": "每天片子的视觉冲击力都是大片级别的"
      },
      {
        "start": 209.32,
        "end": 210.68,
        "text": "最值得一看的是"
      },
      {
        "start": 210.68,
        "end": 212.12,
        "text": "在今年的成品后面"
      },
      {
        "start": 212.12,
        "end": 214.68,
        "text": "它要做轻量化的思路和流程拆解"
      },
      {
        "start": 214.68,
        "end": 216.28,
        "text": "不用很枯燥的教程"
      },
      {
        "start": 216.28,
        "end": 217.92000000000002,
        "text": "你看完不会只觉得好酷"
      },
      {
        "start": 217.92000000000002,
        "end": 219.44,
        "text": "而是知道酷从哪里来"
      },
      {
        "start": 219.44,
        "end": 221.68,
        "text": "就能给到最前一的AI创作玩法"
      },
      {
        "start": 221.68,
        "end": 223.07999999999998,
        "text": "如果你是做视频的"
      },
      {
        "start": 223.07999999999998,
        "end": 225.8,
        "text": "或者单纯想法AI做的不像PVT也只敢"
      },
      {
        "start": 225.8,
        "end": 228.04,
        "text": "它内容是非常值得谷真拉偏的"
      },
      {
        "start": 228.04,
        "end": 229.2,
        "text": "以上这五位博主"
      },
      {
        "start": 229.2,
        "end": 230.48,
        "text": "这上上级的八位"
      },
      {
        "start": 230.48,
        "end": 232.28,
        "text": "不同塞大的AI优质博主"
      },
      {
        "start": 232.28,
        "end": 235.16,
        "text": "都在抖音精选官方IP帳号的手藏家里了"
      },
      {
        "start": 235.16,
        "end": 236.52,
        "text": "选择抖音精选"
      },
      {
        "start": 236.52,
        "end": 238.12,
        "text": "搜索抖音精选的金"
      },
      {
        "start": 238.12,
        "end": 240.76,
        "text": "在对应的手藏家里就能一件打包关注"
      },
      {
        "start": 240.76,
        "end": 242.28,
        "text": "不用一个个灵散去搜"
      },
      {
        "start": 242.28,
        "end": 243.8,
        "text": "省时间又不容易了"
      },
      {
        "start": 243.8,
        "end": 246.04,
        "text": "内容都是经过筛选的优质感火"
      },
      {
        "start": 246.04,
        "end": 247.12,
        "text": "没有选内容"
      },
      {
        "start": 247.12,
        "end": 249,
        "text": "刷到了每一条动的学校东西"
      },
      {
        "start": 249,
        "end": 251.24,
        "text": "特别适合用随便化时间给自己充电"
      },
      {
        "start": 251.24,
        "end": 253.56,
        "text": "不管你是想靠AI提升工作效率"
      },
      {
        "start": 253.56,
        "end": 254.48,
        "text": "熬进的敷衍"
      },
      {
        "start": 254.48,
        "end": 256.32,
        "text": "还是当时想跟上AI趋势"
      },
      {
        "start": 256.32,
        "end": 257.4,
        "text": "关注这些博主"
      },
      {
        "start": 257.4,
        "end": 258.76,
        "text": "都能让你小走弯路"
      },
      {
        "start": 258.76,
        "end": 259.64,
        "text": "快速上手"
      },
      {
        "start": 259.64,
        "end": 261.9,
        "text": "乾淨是抖音精神的收藏家 關注起來吧"
      }
    ],
